<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/config/bootstrap.php';require dirname(__DIR__,2).'/app/admin.php';$admin=admin_require($pdo);
$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');
$sql='SELECT p.id,p.title,p.status,p.updated_at,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE 1=1';$args=[];
if($q!==''){$sql.=' AND (p.title LIKE ? OR p.content LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}
if(in_array($status,['draft','published'],true)){$sql.=' AND p.status=?';$args[]=$status;}
$sql.=' ORDER BY p.updated_at DESC';$stmt=$pdo->prepare($sql);$stmt->execute($args);$posts=$stmt->fetchAll();
admin_header('Articles',$admin);admin_show_flash(); ?>
<section class="content-card"><div class="section-head"><div><h2>All articles</h2><p>Create, edit, publish, or remove stories.</p></div><a class="button" href="<?= e(admin_url('posts/edit.php')) ?>">＋ New article</a></div><form class="filter-form"><input name="q" value="<?= e($q) ?>" placeholder="Search articles…"><select name="status"><option value="">All statuses</option><option value="published" <?= $status==='published'?'selected':'' ?>>Published</option><option value="draft" <?= $status==='draft'?'selected':'' ?>>Draft</option></select><button class="button secondary">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Article</th><th>Category</th><th>Status</th><th>Last update</th><th>Actions</th></tr></thead><tbody><?php foreach($posts as $p): ?><tr><td><strong><?= e($p['title']) ?></strong></td><td><?= e($p['category_name']??'—') ?></td><td><span class="status <?= e($p['status']) ?>"><?= e(ucfirst($p['status'])) ?></span></td><td><?= e(date('M j, Y',strtotime($p['updated_at']))) ?></td><td class="actions"><a href="<?= e(admin_url('posts/edit.php?id='.(int)$p['id'])) ?>">Edit</a><?php if($p['status']==='published'): ?> · <a target="_blank" href="<?= e(site_url('article.php?slug='.rawurlencode($pdo->query('SELECT slug FROM posts WHERE id='.(int)$p['id'])->fetchColumn()))) ?>">View</a><?php endif ?></td></tr><?php endforeach ?><?php if(!$posts): ?><tr><td colspan="5">No matching articles.</td></tr><?php endif ?></tbody></table></div></section><?php admin_footer(); ?>
